<script setup>
import FinancialWorkspace from '../../../Components/Accounting/FinancialWorkspace.vue'
import { ref } from 'vue'
import { Head, Link, router, useForm } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
import Pagination from '../../../Components/Ui/Pagination.vue'
import { useConfirm } from '../../../Composables/useConfirm'
import { localDateInput } from '../../../Utils/dateInput'
import { useFormUx } from '../../../Composables/useFormUx'
defineOptions({layout:AdminLayout})
const props=defineProps({periods:Object,fiscalYears:Array,urls:Object});const {ask}=useConfirm();const now=new Date();const first=localDateInput(new Date(now.getFullYear(),now.getMonth(),1));const last=localDateInput(new Date(now.getFullYear(),now.getMonth()+1,0))
const createForm=useForm({fiscal_year_id:'',name:'',starts_on:first,ends_on:last,notes:''});const editForm=useForm({fiscal_year_id:'',name:'',starts_on:'',ends_on:'',notes:''});const editingId=ref(null)
function edit(period){editingId.value=period.id;Object.assign(editForm,{fiscal_year_id:period.fiscalYearId||'',name:period.name,starts_on:period.startsOn,ends_on:period.endsOn,notes:period.notes||''})}
const saveEdit=(period)=>editForm.put(period.updateUrl,{preserveScroll:true,onSuccess:()=>editingId.value=null});const create=()=>createForm.post(props.urls.store,{preserveScroll:true,onSuccess:()=>{createForm.reset();createForm.starts_on=first;createForm.ends_on=last}})
async function action(period,type){const closing=type==='close';const yes=await ask({title:closing?'إقفال الشهر؟':'إعادة فتح الشهر؟',message:closing?'سيُمنع ترحيل أي قيد جديد داخل مدته بعد فحص الجاهزية، من دون إنشاء قيد أرباح أو خسائر شهري.':'ستعود الفترة لاستقبال القيود، مع بقاء سجل الفتح والإقفال محفوظاً.',confirmLabel:closing?'إقفال الشهر':'إعادة الفتح',danger:closing});if(yes)router.post(closing?period.closeUrl:period.reopenUrl,{}, {preserveScroll:true})}
async function remove(period){const yes=await ask({title:'حذف الشهر الفارغ؟',message:'لن يسمح النظام بالحذف إذا كان الشهر يحتوي قيوداً أو بيانات مرتبطة.',confirmLabel:'حذف',danger:true});if(yes)router.delete(period.destroyUrl,{preserveScroll:true})}
const checkingId = ref(null)
useFormUx(() => [createForm, ...(editingId.value ? [editForm] : [])])
function check(period) { checkingId.value = period.id; router.get(period.checkUrl, {}, { only: ['periods'], preserveState: true, preserveScroll: true, onFinish: () => { checkingId.value = null } }) }
</script>
<template>
<Head title="الفترات الشهرية"/>
<FinancialWorkspace area="المحاسبة" mode="records">
<template #heading>
<PageHeader title="الفترات الشهرية" icon="bi-calendar3" subtitle="مراجعة وإقفال الشهور"/>
</template>
<template #navigation>
<AccountingNav :urls="urls" active="periods"/>
</template>
<section class="period-layout"><AccountingPanel title="إضافة شهر" icon="bi-calendar-plus"><form class="create-form" @submit.prevent="create"><label><span>السنة المالية</span><select v-model="createForm.fiscal_year_id" class="form-select"><option value="">بدون ربط</option><option v-for="year in fiscalYears" :key="year.id" :value="year.id" :disabled="year.closed">{{year.name}}{{year.closed?' — مقفلة':''}}</option></select></label><label><span>اسم الشهر <small>اختياري</small></span><input v-model="createForm.name" class="form-control" placeholder="يُسمّى تلقائياً"></label><div><label><span>من</span><input v-model="createForm.starts_on" type="date" class="form-control" required></label><label><span>إلى</span><input v-model="createForm.ends_on" type="date" class="form-control" required></label></div><label><span>ملاحظات</span><textarea v-model="createForm.notes" rows="2" class="form-control"></textarea></label><button class="btn btn-primary" :disabled="createForm.processing"><i class="bi bi-plus-lg"></i> إضافة الشهر</button></form></AccountingPanel>
<main class="period-list"><article v-for="period in periods.data" :key="period.id" class="period-card" :class="{closed:period.closed}"><header><span class="state"><i class="bi" :class="period.closed?'bi-lock-fill':'bi-unlock-fill'"></i></span><div><span><strong>{{period.name}}</strong><em :class="period.closed?'closed':'open'">{{period.closed?'مقفل':'مفتوح'}}</em><em v-if="period.fiscalYearName">{{period.fiscalYearName}}</em><em v-else class="warn">غير مربوط بسنة</em></span><small><i class="bi bi-calendar-range"></i> {{period.startsOn}} — {{period.endsOn}}</small><p v-if="period.notes">{{period.notes}}</p></div><div class="readiness" :class="{ready:!period.closed&&period.checksLoaded&&!period.issueCount}"><strong v-if="period.closed">تم الإقفال</strong><strong v-else-if="!period.checksLoaded">لم يُفحص بعد</strong><strong v-else-if="!period.issueCount">جاهز للإقفال</strong><strong v-else>{{period.issueCount}} ملاحظة</strong><small v-if="period.closed&&period.closedAt">{{period.closedAt}}</small></div></header><details v-if="!period.closed&&period.issueCount" class="checks"><summary>فحص ما قبل الإقفال</summary><div v-for="(check,i) in period.checks.filter(c=>!c.ok)" :key="i" class="check-row"><strong>{{check.label}} · {{check.severity === 'block' ? 'مانع إقفال' : 'تنبيه للمراجعة'}}</strong><span>{{check.detail}}</span><small>{{check.message}}</small><Link v-if="check.url" :href="check.url">فتح السجلات ومعالجة السبب</Link></div></details><div class="card-actions"><button v-if="!period.closed" type="button" :disabled="checkingId !== null" @click="check(period)"><i class="bi bi-list-check"></i> {{ checkingId === period.id ? 'جارٍ الفحص…' : 'فحص الإقفال' }}</button><button v-if="!period.closed" type="button" @click="edit(period)"><i class="bi bi-pencil"></i> تعديل</button><button v-if="!period.closed" type="button" class="delete" @click="remove(period)"><i class="bi bi-trash3"></i></button><span></span><button v-if="period.closed" type="button" class="reopen" @click="action(period,'reopen')"><i class="bi bi-unlock"></i> إعادة فتح</button><button v-else type="button" class="close" @click="action(period,'close')"><i class="bi bi-lock"></i> إقفال الشهر</button></div><form v-if="editingId===period.id" class="edit-form" @submit.prevent="saveEdit(period)"><label><span>الاسم</span><input v-model="editForm.name" class="form-control" required></label><label><span>السنة</span><select v-model="editForm.fiscal_year_id" class="form-select"><option value="">بدون ربط</option><option v-for="year in fiscalYears" :key="year.id" :value="year.id">{{year.name}}</option></select></label><label><span>من</span><input v-model="editForm.starts_on" type="date" class="form-control" required></label><label><span>إلى</span><input v-model="editForm.ends_on" type="date" class="form-control" required></label><label class="notes"><span>ملاحظات</span><input v-model="editForm.notes" class="form-control"></label><button class="btn btn-primary"><i class="bi bi-check2"></i> حفظ</button><button type="button" class="btn btn-light" @click="editingId=null">إلغاء</button></form></article><div v-if="!periods.data.length" class="empty"><i class="bi bi-calendar-x"></i><strong>لا توجد شهور محاسبية</strong><span>أنشئ سنة مالية مع شهورها أو أضف أول شهر.</span></div><Pagination :links="periods.links"/></main></section>
</FinancialWorkspace>

</template>
<style scoped>.check-row{display:grid;gap:5px;padding:12px 0;border-top:1px solid #e4d1ab}.check-row a{display:block;width:fit-content;padding:8px 10px;background:var(--surface);border:1px solid #b78338;border-radius:6px;color:#784900;font-weight:700}.check-row small{font-size:14px}.period-layout{display:grid;grid-template-columns:minmax(280px,.65fr) minmax(0,1.35fr);align-items:start;gap:11px}.period-layout>:first-child{position:sticky;top:183px}.create-form{display:grid;gap:10px}.create-form label,.edit-form label{display:grid;gap:4px}.create-form label>span,.edit-form label>span{font-size:.875rem;font-weight:850}.create-form label span small{color:var(--muted, #626B6D);font-size:.875rem;font-weight:500}.create-form>div{display:grid;grid-template-columns:1fr 1fr;gap:8px}.period-list{display:grid;gap:9px}.period-card{overflow:hidden;border:1px solid var(--line, #DFD7CB);border-inline-start:4px solid #A3422B;border-radius:12px;background:var(--surface, #FFFDFA)}.period-card.closed{border-inline-start-color:#A3422B}.period-card>header{display:grid;grid-template-columns:auto 1fr auto;align-items:start;gap:10px;padding:14px}.state{display:grid;width:38px;height:38px;place-items:center;border-radius:11px;color:var(--ink, #25343A);background:var(--brand-soft, #F3E3D8)}.closed .state{color:var(--muted, #626B6D);background:var(--surface-muted, #EFE9E0)}.period-card header>div:nth-child(2){display:grid;gap:4px}.period-card header>div>span{display:flex;align-items:center;gap:6px}.period-card header strong{font-size:.875rem}.period-card header em{padding:2px 6px;border-radius:12px;color:var(--muted, #626B6D);background:var(--surface, #FFFDFA);font-size:.875rem;font-style:normal}.period-card header em.open{color:var(--ink, #25343A);background:var(--brand-soft, #F3E3D8)}.period-card header em.closed{color:var(--muted, #626B6D)}.period-card header em.warn{color:#a35b00;background:#fff0dc}.period-card header small,.period-card header p{margin:0;color:var(--muted, #626B6D);font-size:.875rem}.readiness{display:grid;justify-items:end;color:#a35b00}.readiness.ready{color:#A3422B}.readiness strong{font-size:.875rem}.checks{margin:0 14px 10px;padding:9px 11px;border-radius:10px;color:#8f5400;background:#fff7e7}.checks summary{cursor:pointer;font-size:.875rem;font-weight:850}.checks>span{display:flex;gap:6px;margin-top:5px;font-size:.875rem}.card-actions{display:flex;align-items:center;gap:6px;padding:9px 14px;border-top:1px solid var(--line, #DFD7CB)}.card-actions span{flex:1}.card-actions button{padding:6px 9px;border:1px solid var(--line, #DFD7CB);border-radius:8px;color:var(--muted, #626B6D);background:var(--surface, #FFFDFA);font-size:.875rem;font-weight:800}.card-actions .delete{color:#ad2c2c}.card-actions .close{color:#fff;border-color:#A3422B;background:var(--brand, #A3422B)}.card-actions .reopen{color:#945600;border-color:#e1be7a}.edit-form{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;align-items:end;gap:8px;padding:11px 14px;border-top:1px solid var(--line, #DFD7CB);background:var(--surface, #FFFDFA)}.edit-form .notes{grid-column:1/4}.empty{display:grid;justify-items:center;gap:4px;padding:60px;border:1px dashed var(--line, #DFD7CB);border-radius:12px;color:var(--muted, #626B6D);background:var(--surface, #FFFDFA)}.empty i{font-size:1.5rem}.empty strong{font-size:.875rem}.empty span{font-size:.875rem}@media(max-width:1000px){.period-layout{grid-template-columns:1fr}.period-layout>:first-child{position:static}.create-form{grid-template-columns:1fr 1fr}.create-form>div{grid-column:1/-1}.create-form button{align-self:end}}@media(max-width:650px){.create-form{grid-template-columns:1fr}.create-form>div{grid-column:auto}.period-card>header{grid-template-columns:auto 1fr}.readiness{grid-column:2;justify-items:start}.edit-form{grid-template-columns:1fr 1fr}.edit-form .notes{grid-column:1/-1}}</style>
